def solve(g):
    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    walls=[i for i,r in enumerate(g) if 8 in r]
    wet={(i,j) for i,r in enumerate(g) for j,v in enumerate(r) if v==2 and i not in walls}
    out=[r[:] for r in g]
    for w in walls:
        gaps=[j for j,v in enumerate(g[w]) if v==0]
        a=w-1
        wet={(i,j) for (i,j) in wet if i<=a}
        # mark fall paths
        byc={}
        for (i,j) in wet: byc.setdefault(j,[]).append(i)
        cols=set(byc)
        for j in cols:
            top=min(byc[j])
            for i in range(top,a+1): out[i][j]=2
        wet={(a,j) for j in cols}
        covered=set(cols)
        for c in cols:
            j=c
            while j-1>=0 and (j-1) not in gaps: j-=1
            covered.update(range(j,c))
            if j-1>=0: covered.add(j-1)
            j=c
            while j+1<W and (j+1) not in gaps: j+=1
            covered.update(range(c+1,j+2 if j+1<W else j+1))
            if j+1<W: covered.add(j+1)
        for k in covered: out[a][k]=2
        wet={(w,j) for j in gaps if j in covered}
        for (i,j) in wet: out[i][j]=2
    byc={}
    for (i,j) in wet: byc.setdefault(j,[]).append(i)
    for j,rows in byc.items():
        for i in range(min(rows),H): out[i][j]=2
    return out

